 "<div style=\"font-size:22px;font-weight:700;color:#ffb81c;\">Ofrenda</div><span style=\"font-size:19px;color:#f6eefc\">Altar con fotos, comida y flores para recordar a los difuntos.</span>": "<div style=\"font-size:22px;font-weight:700;color:#ffb81c;\">Ofrenda (Opfergabe)</div><span style=\"font-size:19px;color:#f6eefc\">Ein Altar mit Fotos, Essen und Blumen zum Gedenken an die Verstorbenen.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#f472b6;\">Calavera</div><span style=\"font-size:19px;color:#f6eefc\">Cráneo; en México, figura alegre de azúcar o dibujo.</span>": "<div style=\"font-size:22px;font-weight:700;color:#f472b6;\">Calavera (Schädel)</div><span style=\"font-size:19px;color:#f6eefc\">Ein Schädel; in Mexiko eine fröhliche Figur aus Zucker oder eine Zeichnung.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#f58a1f;\">Disfraz</div><span style=\"font-size:19px;color:#f6eefc\">Ropa con la que alguien se transforma en otro personaje.</span>": "<div style=\"font-size:22px;font-weight:700;color:#f58a1f;\">Disfraz (Verkleidung)</div><span style=\"font-size:19px;color:#f6eefc\">Kleidung, mit der sich jemand in eine andere Figur verwandelt.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#a78bfa;\">Truco o trato</div><span style=\"font-size:19px;color:#f6eefc\">Pedir dulces de puerta en puerta a cambio de una broma.</span>": "<div style=\"font-size:22px;font-weight:700;color:#a78bfa;\">Truco o trato (Süßes oder Saures)</div><span style=\"font-size:19px;color:#f6eefc\">Von Tür zu Tür um Süßigkeiten bitten, im Tausch gegen einen Streich.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#6fcf97;\">Difuntos</div><span style=\"font-size:19px;color:#f6eefc\">Personas que han fallecido.</span>": "<div style=\"font-size:22px;font-weight:700;color:#6fcf97;\">Difuntos (Verstorbene)</div><span style=\"font-size:19px;color:#f6eefc\">Menschen, die gestorben sind.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#ffb81c;\">Panellets</div><span style=\"font-size:19px;color:#f6eefc\">Dulces catalanes de almendra, típicos de la Castañada.</span>": "<div style=\"font-size:22px;font-weight:700;color:#ffb81c;\">Panellets</div><span style=\"font-size:19px;color:#f6eefc\">Katalanisches Mandelgebäck, typisch für die Castañada.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#f58a1f;\">Cempasúchil</div><span style=\"font-size:19px;color:#f6eefc\">Flor naranja del Día de Muertos.</span>": "<div style=\"font-size:22px;font-weight:700;color:#f58a1f;\">Cempasúchil</div><span style=\"font-size:19px;color:#f6eefc\">Die orangefarbene Blume des Día de Muertos.</span>",
 "<div style=\"font-size:22px;font-weight:700;color:#a78bfa;\">Magosto</div><span style=\"font-size:19px;color:#f6eefc\">Fiesta de las castañas asadas en Galicia.</span>": "<div style=\"font-size:22px;font-weight:700;color:#a78bfa;\">Magosto</div><span style=\"font-size:19px;color:#f6eefc\">Fest der gerösteten Kastanien in Galicien.</span>",
